    excerpt:
      'В каждых переговорах работают десятки когнитивных искажений - с обеих сторон. Тот, кто их распознаёт и использует осознанно, получает стратегическое преимущество. Разбираем 7 ключевых искажений с конкретными тактиками.',
    content: `Когнитивные искажения - это систематические ошибки мышления, возникающие из-за особенностей работы человеческого мозга. В переговорах они работают одновременно у всех участников, создавая предсказуемые паттерны поведения. Понимание этих паттернов - мощнейшее конкурентное преимущество.

Семь ключевых искажений в переговорах: 1) Эффект владения (endowment effect) - продавец всегда переоценивает то, что продаёт. Зная это, покупатель может использовать вопросы, помогающие продавцу самому снизить планку. 2) Самоуверенность (overconfidence bias) - обе стороны верят в свою силу позиции сильнее, чем оправдано. 3) Предвзятость подтверждения - поиск только тех данных, которые подтверждают уже принятое решение. 4) Эффект фрейминга - одно и то же условие воспринимается по-разному в зависимости от формулировки.

5) Иллюзия контроля - переоценка собственного влияния на исход. 6) Эффект статус-кво - нежелание менять текущее положение дел даже в ущерб себе. 7) Туннельное мышление - фиксация на одном параметре (чаще всего цене) в ущерб комплексному анализу. Опытный переговорщик умеет целенаправленно «включать» нужные искажения в собеседнике.

Практическая техника работы с искажениями включает три шага. Сначала - диагностика: какие искажения активны у вашего оппонента прямо сейчас? Затем - использование: как структурировать вашу подачу информации, чтобы работать с этими искажениями? Наконец - самозащита: как убедиться, что вы сами не попали в ловушку искажения? Лучшие переговорщики ведут мысленный «реестр» когнитивных состояний за столом - это требует практики, но кардинально меняет результаты.`,
