    excerpt:
      'Исследования показывают: менеджеры с высоким EQ продают на 50% больше коллег с аналогичными техническими знаниями. Эмоциональный интеллект поддаётся развитию - разбираем конкретные практики для команды продаж.',
    content: `Эмоциональный интеллект (EQ) - способность распознавать, понимать и управлять собственными эмоциями и эмоциями других людей. Концепция, введённая Питером Саловеем и Джоном Майером в 1990 году и популяризованная Дэниэлом Гоулманом, имеет прямую корреляцию с эффективностью в продажах. Мета-анализ 28 исследований показал: EQ объясняет от 27 до 45% дисперсии в результатах продавцов.

EQ состоит из четырёх компонентов, каждый из которых по-своему влияет на продажи. Самосознание (self-awareness) позволяет продавцу понимать, как его эмоциональное состояние влияет на разговор. Самоуправление (self-regulation) - способность оставаться спокойным под давлением, не реагировать защитно на отказы и контролировать импульсы. Социальное осознание (social awareness) - умение читать эмоциональное состояние клиента, улавливать невербальные сигналы. Управление отношениями (relationship management) - построение доверия и навигация по сложным социальным ситуациям.

Ключевой навык для продавца - эмпатия, как точная модель внутреннего состояния клиента. Но важно разграничить когнитивную эмпатию (понимаю, что ты чувствуешь) и аффективную (разделяю твои чувства). Для эффективных продаж нужна первая - она сохраняет ясность мышления. Продавцы с высокой аффективной эмпатией часто «заражаются» тревогой клиента и теряют позицию.

Развитие EQ для продавцов: ведение дневника эмоций после каждой встречи (что я почувствовал, что почувствовал клиент), практика осознанности для улучшения самоуправления, ролевые игры с разбором эмоциональной динамики. Компании, внедрившие EQ-тренинги, сообщают о среднем приросте продаж 20-30% у участников в течение первых шести месяцев.`,
