    title: 'Как победить выгорание и страхи: техники психотерапии и внутренней поддержки',
    excerpt: 'Выгорание - сигнал хронического стресса и рутины. Телесные практики, когнитивная терапия и работа с внутренним критиком помогают восстановить ресурс и вернуть вкус к работе и жизни.',
    content: `Чувство безысходности, усталости, раздражение на коллег и рутина - всё это признаки выгорания, которое разрушает внутренний ресурс и мешает двигаться вперёд. Выгорание - это состояние эмоционального истощения, вызванное хроническим стрессом.

По данным исследований, от профессионального выгорания страдают до 67% специалистов в сфере продаж и управления. При этом большинство продолжают работать «через силу», усугубляя ситуацию.

Техники восстановления:

1. Движение и растяжка: освобождают зажатость, повышают уровень энергии и дофамина. Представьте, где в теле выгорание, и отпустите его на выдохе.

2. Эмоционально-образная терапия: создайте образ внутреннего ресурса - представьте место, где вы чувствуете спокойствие и силу.

3. Когнитивная терапия: выявите автоматические мысли («я никогда не достигну успеха»), замените их на более адекватные: «Я делаю всё, что могу, и у меня есть возможности для развития».

4. Практика благодарности: ежедневно записывайте 3 вещи, за которые можете быть благодарны. Это повышает уровень дофамина и окситоцина.

5. Работа с внутренним критиком: научитесь замечать и оспаривать негативные установки. Задавайте вопросы: «Что я могу сделать прямо сейчас, чтобы почувствовать себя лучше?»

6. Осознайте свои страхи: запишите их и проработайте, что реально в этих страхах.

7. Разработайте план небольших шагов, которые помогут почувствовать контроль.

Выгорание и страхи - это сигнал организма о необходимости внимания и заботы о себе. Используйте техники гештальта, телесной, эмоционально-образной и когнитивной терапии для восстановления внутренней силы. Помните: ваш ресурс восстанавливается - нужно лишь дать ему правильный толчок.`,
