    title: 'Воронка продаж: анализ и оптимизация конверсии',
    excerpt:
      'Воронка продаж - не просто визуализация, это диагностический инструмент. Конверсия между этапами говорит о конкретных проблемах в процессе. Разбираем, как читать воронку и где искать точки максимального роста.',
    content: `Воронка продаж как концепция существует с 1898 года (модель AIDA Сент-Элмо Льюиса), но как аналитический инструмент стала по-настоящему мощной только с появлением CRM. Современная воронка - это не просто «сколько на каком этапе», это система раннего предупреждения, позволяющая увидеть проблемы до того, как они ударят по выручке.

Анализ воронки начинается с определения «узких мест» - этапов с аномально низкой конверсией. Средние бенчмарки по B2B: лид → квалификация 40-60%, квалификация → встреча 30-50%, встреча → КП 50-70%, КП → договор 25-40%, договор → оплата 80-95%. Значительное отклонение вниз сигнализирует о системной проблеме именно на этом переходе.

Частые причины низких конверсий: лид → квалификация: некачественный трафик или слабые скрипты первого контакта. Встреча → КП: слабая диагностика потребностей на встрече (SPIN не работает). КП → договор: КП не адресует реальные боли клиента, выявленные на встрече, или нет конкретного следующего шага. Договор → оплата: юридические/финансовые барьеры, не проработанные заранее.

Оптимизация воронки должна идти сверху вниз - начинайте с самого «дырявого» этапа. Увеличение конверсии на 10% на каждом из пяти этапов при начальных значениях 50/40/60/30/90% даёт прирост итоговой конверсии лид→оплата более чем в 2 раза (с 3,2% до 7,9%). Инструменты: запись звонков и встреч для анализа, A/B тестирование КП, mystery shopping, NPS отказавшихся клиентов (самые честные отзывы).`,
