    title: 'Работа с возражениями: 10 техник с примерами',
    excerpt:
      'Возражение - не отказ, а запрос дополнительной информации. Понимание психологии возражений и владение конкретными техниками трансформирует «нет» в «давайте подумаем». Разбираем 10 техник с реальными диалогами.',
    content: `Возражение - это сигнал вовлечённости. Клиент, который молча согласился со всем и ушёл подумать, опаснее того, кто спорит. Возражение говорит: «Я рассматриваю вашу идею, но у меня есть барьер». Задача продавца - найти и убрать барьер, а не «преодолеть» возражение силой аргументов.

Десять ключевых техник. 1) Присоединение: сначала согласитесь с правом клиента так думать («Да, это важный момент»), потом задайте вопрос. 2) Уточнение: «Что именно вас беспокоит в этом?» - часто первое возражение не настоящее. 3) Бумеранг: превратите возражение в аргумент («Именно поэтому...»). 4) Метод «да, и»: добавьте контекст, не отрицая. 5) Апелляция к логике: разберите возражение на составные части и проверьте каждую.

6) Истории клиентов: «У нас был клиент в схожей ситуации...» - социальное доказательство для конкретного возражения. 7) Гипотетическое устранение: «Если бы этого не было, вы бы двигались вперёд?» - проверка, настоящее ли возражение или ложное. 8) Масштабирование: «По шкале от 1 до 10, насколько это критично?» - снижает эмоциональный накал. 9) Разделение: разберите возражение о цене на стоимость vs ценность. 10) Условное согласие: «Если я могу показать вам X, вы готовы двигаться вперёд?»

Наиболее частые возражения в B2B и их психологический корень: «Дорого» - чаще всего означает «я не понимаю ценности» или «у меня нет бюджета прямо сейчас» (разные ответы). «Нам нужно подумать» - «не хочу принимать решение под давлением» или «не мой бюджет». «Работаем с другим поставщиком» - «боюсь смены и рисков». Правильная диагностика психологического корня возражения - 80% успеха ответа.`,
